/**
 * T10_F375 „Das Netz als Karte“ (6.4, 6.6): the small, quiet line of the map. What Luna knows in
 * this mode („1.240 Einträge · 38 Felder · 12 neu seit gestern“, only with the capability
 * knowledge-graph-growth), or a search's glow line while his words glow. T10_F592 (universe U554):
 * the line lies on the map's top left corner, so the map keeps the whole height; it names the mode
 * when it is not the first one, and a glow line has a small × that empties the search. Where the
 * line does not fit, its „neu“ part goes first (screen readers still hear it); a word is never cut. On the phone the page's i
 * stands right after it (`info`, the app's InfoButton); on a wide window the i is in the bar (src/screens/Memory.tsx).
 */

import type { ComponentChildren } from "preact";
import { useLayoutEffect, useRef, useState } from "preact/hooks";
import { T } from "../../text";
import { CloseIcon } from "../icons";

/** The line without its last part when that part tells what is new; null when there is none. */
export function withoutNew(text: string): string | null {
  const parts = text.split(" · ");
  return parts.length > 1 && /\bneu\b/.test(parts[parts.length - 1]!) ? parts.slice(0, -1).join(" · ") : null;
}

export function NetHeader({ line, glow, place, onClear, info }: { line: string | null; glow: string | null; place?: string | null; onClear?: () => void; info?: ComponentChildren }) {
  const full = glow ?? (line && place ? `${place} · ${line}` : (line ?? place ?? ""));
  const short = glow ? null : withoutNew(full);
  const head = useRef<HTMLDivElement>(null);
  const measure = useRef<HTMLSpanElement>(null);
  const [fits, setFits] = useState(true);
  useLayoutEffect(() => {
    const box = head.current;
    if (!box || !short) return setFits(true);
    const check = () => {
      const gap = parseFloat(getComputedStyle(box).columnGap) || 0;
      const others = [...box.children].filter((el) => el.tagName === "BUTTON" || el.classList.contains("net__info")) as HTMLElement[];
      const room = box.clientWidth - others.reduce((sum, el) => sum + el.offsetWidth + gap, 0);
      setFits((measure.current?.offsetWidth ?? 0) <= room);
    };
    check();
    if (typeof ResizeObserver === "undefined") return;
    let frame = 0;
    const observer = new ResizeObserver(() => {
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(check);
    });
    observer.observe(box);
    return () => {
      cancelAnimationFrame(frame);
      observer.disconnect();
    };
  }, [full, short]);
  const cut = !fits && short !== null;
  return (
    <div class="net__head" ref={head} hidden={!full && !info}>
      <span class="net__measure" ref={measure} aria-hidden="true">
        {full}
      </span>
      {full ? (
        <p class="net__line" data-testid={glow ? "net-glow-line" : "net-stats"} role="status">
          {cut ? short : full}
          {cut ? <span class="visually-hidden">{full.slice(short.length)}</span> : null}
        </p>
      ) : null}
      {glow && onClear ? (
        <button type="button" class="net__clear" data-testid="net-clear" aria-label={T.net.clearSearch} title={T.net.clearSearch} onClick={onClear}>
          <CloseIcon />
        </button>
      ) : null}
      {info ? <span class="net__info">{info}</span> : null}
    </div>
  );
}
